static inline double MODEL_TEMP_predict_one(const double* x) {
    double s = 0.0;
    for (int t = 0; t < MODEL_TEMP_NUM_TREES; t++) {
        int node = MODEL_TEMP_tree_roots[t];
        while (!MODEL_TEMP_nodes[node].is_leaf) {
            const MODEL_TEMP_node_t* n = &MODEL_TEMP_nodes[node];
            node = (x[n->feature] <= n->threshold) ? n->left : n->right;
        }
        s += MODEL_TEMP_nodes[node].value;
    }
    return s;
}

